static boolean hasRaceCondition(int threadCount, int incrementsPerThread) throws InterruptedException {
    int[] counter = {0};
    Thread[] watki = new Thread[threadCount];
    for (int i=0;i<threadCount;i++) watki[i] = new Thread(() -> { for (int j=0;j<incrementsPerThread;j++) counter[0]++; });
    for (Thread t : watki) t.start();
    for (Thread t : watki) t.join(10_000);
    return counter[0] != threadCount * incrementsPerThread;
}
int bledy = 0;
for (int i=0;i<5;i++) if (hasRaceCondition(4, 100_000)) bledy++;
System.out.println(bledy+"/5 prob mialo race condition");

