static List<String> auditCommonMistakes(String kod) {
    List<String> problemy = new ArrayList<>();
    if (kod.contains(".run()") && !kod.contains(".start()")) problemy.add("Blad 1: run() zamiast start()");
    if (kod.contains("count++") && !kod.contains("synchronized") && !kod.contains("Atomic")) problemy.add("Blad 3: nieatomowa inkrementacja");
    if (kod.contains(".wait()") && !kod.contains("synchronized")) problemy.add("Blad 4: wait() poza synchronized");
    if (kod.contains(".notify()") && !kod.contains(".notifyAll()")) problemy.add("Blad 5: notify() zamiast notifyAll() (moze byc OK, sprawdz recznie)");
    return problemy;
}
System.out.println(auditCommonMistakes("thread.run(); count++;"));

