class ModernWorker {
    AtomicInteger counter = new AtomicInteger(0);
    final Object lock = new Object();
    boolean ready = false;
    void runCorrectly() throws InterruptedException {
        Thread t = new Thread(() -> { for (int i=0;i<1000;i++) counter.incrementAndGet(); });
        t.start(); // NIE run()
        t.join(2000); // z join()
    }
    void waitCorrectly() throws InterruptedException {
        synchronized (lock) { while (!ready) lock.wait(100); } // wait() W synchronized
    }
    void notifyCorrectly() {
        synchronized (lock) { ready = true; lock.notifyAll(); } // notifyAll() nie notify()
    }
}
ModernWorker w = new ModernWorker();
w.runCorrectly();
System.out.println(w.counter.get() == 1000);

static String diagnose(String kod) {
    if (kod.contains(".run()") && !kod.contains(".start()")) return "Blad 1: run() zamiast start()";
    if (kod.contains("count++") && !kod.contains("Atomic") && !kod.contains("synchronized")) return "Blad 3: race condition";
    if (kod.contains(".wait()") && !kod.contains("synchronized")) return "Blad 4: wait() poza synchronized";
    if (kod.contains(".notify()") && !kod.contains("notifyAll")) return "Blad 5 (mozliwy): notify() zamiast notifyAll()";
    return "poprawny kod";
}
String[] fragmenty = { "thread.run();", "thread.start(); thread.join();", "counter.incrementAndGet();" };
for (String f : fragmenty) System.out.println(diagnose(f));

static boolean askCandidateQuestion(int nr, String odpowiedz) {
    Map<Integer,String> oczekiwane = Map.of(1,"start", 2,"join", 3,"atomic", 4,"synchronized", 5,"notifyall", 6,"shutdown");
    return odpowiedz.toLowerCase().contains(oczekiwane.get(nr));
}
System.out.println(askCandidateQuestion(5, "trzeba uzyc notifyAll zamiast notify")); // true
System.out.println(askCandidateQuestion(5, "nie wiem")); // false

BlockingQueue<Integer> zadania = new ArrayBlockingQueue<>(30); // unika Bledu 2: komunikacja zamiast recznego 'zgadywania' stanu
for (int i=1;i<=30;i++) zadania.put(i);
AtomicInteger przetworzone = new AtomicInteger(0); // unika Bledu 3: atomowy licznik zamiast zwyklego int
ExecutorService pool = Executors.newFixedThreadPool(4); // unika Bledu 1: start() przez submit(), nie run()
for (int i=0;i<30;i++) pool.submit(() -> { Integer z = zadania.poll(); if (z != null) przetworzone.incrementAndGet(); });
pool.shutdown(); // unika Bledu 6
pool.awaitTermination(5, TimeUnit.SECONDS); // unika Bledu 2 (czekamy na zakonczenie)
System.out.println("przetworzono: "+przetworzone.get()+"/30 - system dziala bezblednie, unikajac WSZYSTKICH 6 typowych bledow");
